using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.CayleySumCodes;

internal sealed class DihedralOldNecessityCounterexampleDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Dihedral necessity counterexample", H("Actual finite-group refutation"),
        Blocks(Describe.Lean(DescribeId.Create("dihedraloldnecessitycounterexample-refutation"),
            DeclarationHandle.Create("D5/S3/Combinatorics/CayleySumCodes/DihedralOldNecessityCounterexample.result"),
            H("The source counterexample"), StatementSource.WithoutFormula(),
            AssessedProvenance.FromLiterature(LibraryNoteRef.Create(
                "D5/L/FiniteGroups/manikandishzhang2026sumcodes")),
            Blocks(Paragraph(Text("The source Example2.3(2) uses the actual DihedralGroup4 of order8, H=G and the normal connection set {1,a squared}. Center and square set are exactly those two elements; the loopless sum graph is a perfect matching. Both possible normal transversals of G in itself consist of squares. This is the full second source counterexample to the old necessity, with no claim against its surviving sufficient direction."))), DescribeRole.Theorem),
            Paragraph(Text("Dihedral applications of the subgroup code criteria. The following sufficient constructions are Zhang arXiv:2210.03336v1, Examples 5.6–5.8, distinguished from the old exhaustive claim in Theorem 5.10 by the Ma–Nikandish–Zhang correction cited above. Their source attribution and license information are those of the same library note. Write R=ZMod n for every natural n, and D=DihedralGroup n with rotations r(i) and reflections sr(i), i∈R. The multiplication conventions are r(i)r(j)=r(i+j), r(i)sr(j)=sr(j-i), sr(i)r(j)=sr(i+j), sr(i)sr(j)=r(j-i); inverses are r(i)⁻¹=r(−i), sr(i)⁻¹=sr(i), and 1=r(0). All the constructions use the actual loopless graph: g is adjacent to x exactly when g≠x and gx lies in the stated connection set. They give sufficient applications, not additional exhaustive classifications.")),
            Paragraph(Text("For each c∈R let H_c={1,sr(c)}. This is a subgroup because sr(c)²=1 and the inverse of sr(c) is itself. Let Y_ref={sr(i):i∈R}. Conjugating any reflection by either a rotation or reflection again gives a reflection, by the four multiplication formulas, so Y_ref is normal as a subset. Two vertices are adjacent exactly when one is a rotation and the other a reflection: their product is a reflection and they are unequal, whereas products of vertices in the same part are rotations and cannot lie in Y_ref. Thus for n>0 the graph is the full K_{n,n}, with n elements in each part. For n=0, R=Z and both parts are infinite; it is the corresponding infinite complete bipartite graph. There is no parity or lower-bound assumption on n.")),
            Paragraph(Text("For every n∈ℕ and every c∈ZMod n, H_c is a total perfect code for Y_ref. A rotation r(i) has sr(c) as its unique H_c-neighbor: 1 is in the rotation part and is never adjacent to r(i), including i=0 where it is the vertex itself. A reflection sr(i) has 1 as its unique H_c-neighbor: sr(c) is in the same part and cannot be adjacent, including i=c. These are all code vertices. This proves the construction for all n, retaining the finite source domain and the additional n=0 boundary separately.")),
            Paragraph(Text("For every n∈ℕ, every additive homomorphism e:R→ZMod 2 and every c∈R, define Y_{e,c} by r(i)∈Y_{e,c} iff e(i)=1 and sr(i)∈Y_{e,c} iff e(i)=e(c). In ZMod 2 one has −x=x, x+x=0, and x-y=1 iff x≠y. Under conjugation by a rotation or reflection the rotation index becomes j or −j, and a reflection index becomes j−2i or 2i−j. Additivity of e and these characteristic-two identities preserve both membership conditions. Thus Y_{e,c} is conjugation invariant for every such e, even a zero or nonsurjective character.")),
            Paragraph(Text("The subgroup H_c is a total code for Y_{e,c}. For a rotation r(i), if e(i)=1, the unique code neighbor is 1; i≠0 follows from e(0)=0, and the other candidate sr(c) would require e(c-i)=e(c), forcing e(i)=0. If e(i)≠1, the two-element codomain gives e(i)=0; then sr(c) is its neighbor because e(c-i)=e(c), whereas 1 would require e(i)=1. For a reflection sr(i), if e(i)=e(c), its unique code neighbor is 1 and the other candidate would require e(c-i)=1, although e(c-i)=0. If e(i)≠e(c), its unique code neighbor is sr(c), since e(c-i)=1; i≠c follows by applying e, so this is not a loop. The candidate 1 is excluded by its membership test. This covers all four cases and proves uniqueness without a surjectivity premise.")),
            Paragraph(Text("For the source even rotation domain n=2*l, l∈ℕ, the actual character is the additive part of the quotient homomorphism ZMod(2*l)→ZMod 2 induced by 2 dividing 2*l: e([i])=[i] modulo 2. At l=0 it is ordinary parity on Z. The choices c=0 and c=−1 recover both source parity families: odd rotations together with even reflections, or odd rotations together with odd reflections, respectively. More generally every reflection c gives the same conclusion with its own parity class; no replacement of a reflection by a scalar proxy is involved.")),
            Paragraph(Text("For the central-half-turn family let n∈ℕ, h∈R with h+h=0, and h≠0. Put K={0,h}≤R additively and H={1,r(h)}≤D. Both are subgroups: sums or products of the nonidentity generator return the identity, and −h=h. Let Z⊆R be any actual additive transversal of K, meaning for each i∈R there is exactly one z∈Z with −z+i∈K. Assume Z is inverse closed, meaning for every i∈Z also −i∈Z. Let e:R→ZMod 2 be any additive homomorphism with e(h)=1 and let c∈ZMod 2 be either value. These are the complete parameter hypotheses; there is no prescribed internal representative of Z, no graph premise and no code premise.")),
            Paragraph(Text("The transversal property gives i∈Z iff i+h∉Z for every i. If both belonged to Z, they would represent the same K-coset of i because −i+i=0 and −(i+h)+i=h; uniqueness would force i=i+h and hence h=0. Conversely the representative z of i satisfies −z+i=0 or h, so z=i or z=i+h, and absence of i+h forces i∈Z. Replace the internal representative by h: define S=(Z excluding {0,h})∪{h}, or explicitly i∈S iff (i∈Z and i≠0 and i≠h) or i=h. Then 0∉S, h∈S, and i∈S iff i+h∉S. For i=0 or i=h this follows from the two memberships just stated and h+h=0. Otherwise i+h is also neither 0 nor h, and the preceding transversal equivalence applies. In particular either possible representative 0 or h of the internal K-coset is allowed.")),
            Paragraph(Text("Define Y by r(i)∈Y iff i∈S and sr(i)∈Y iff e(i)=c. The set S is inverse closed: if i∈Z outside {0,h}, then −i∈Z, −i≠0, and −i≠h since −h=h; the selected element h is its own inverse. Consequently conjugation preserves the rotation condition, since its index becomes i or −i. For reflections the index becomes j−2i or 2i−j, which has the same e-value as j. This proves NormalSubset Y for every inverse-closed Z under h+h=0; the transversal and e(h)=1 are not needed for normality.")),
            Paragraph(Text("Under all the parameter hypotheses, H is a total code for Y. For r(i) with i∈S, its neighbor is 1: it is distinct because 0∉S, and the other candidate r(h) would require i+h∈S, contrary to the pair equivalence. For i∉S, its neighbor is r(h), because i+h∈S; equality r(i)=r(h) would give i=h∈S, a contradiction. The candidate 1 fails its membership test. For sr(i) with e(i)=c, its neighbor is 1; rotation/reflection separation ensures distinctness, and adjacency to r(h) would require e(i+h)=c, but e(i+h)=e(i)+1≠c. If e(i)≠c, then e(i)+1=c in ZMod 2, so r(h) is the neighbor, with 1 excluded. These four branches exhaust the two-element code and establish existence and uniqueness at every vertex, including the two vertices in H.")),
            Paragraph(Text("The subgroup H is normal in D: conjugation fixes r(h) or replaces it by r(−h)=r(h), by the multiplication formulas and h+h=0. Form the perfect-code connection P=Y excluding H. Explicitly P consists of the rotations from Z outside {0,h} and the same selected reflection parity class. It is conjugation invariant because Y is and H is a normal subgroup; if a conjugate lay in H, conjugation back would put the original element in H. For every parameter tuple above, H is a perfect code in CS(D,P). If g∈H, its unique closed-neighborhood code vertex is itself: another code vertex x would have gx∈H and hence gx∉P. If g∉H, its unique total-code neighbor x for Y still works for P, since gx∈H together with x∈H would imply g=(gx)x⁻¹∈H. Conversely every P-neighbor is a Y-neighbor, so uniqueness is preserved, and g cannot equal a code vertex. This proves the perfect-code construction for exactly the same Z and either reflection class, without taking total coding as an extra hypothesis.")),
            Paragraph(Text("In the original finite source family n=4*k+2 with k≥1, choose h=[2*k+1] and the parity character e:ZMod(4*k+2)→ZMod 2. Then 2h=[4*k+2]=0, h≠0 because 0<2*k+1<4*k+2, and e(h)=1 because 2*k+1 is odd. Hence every inverse-closed additive transversal Z of {0,h} and either c=0 or c=1 satisfy the displayed domain, and both total and perfect connections above apply. This includes either choice of the internal representative, not only a normalized Z containing 0. The abstract constructions retain n=0 as well: in R=Z, h+h=0 forces h=0, so no nonzero-half-turn tuple exists there; the reflection and parity constructions still apply in that infinite model. None of these sufficient constructions repairs the false old necessity or asserts that the listed families exhaust all total-code graphs."))),
        [DocumentEdge.Dependency.Create(GidRef.Create(
            "D5/S3/Combinatorics/CayleySumCodes/TotalPerfectCriterion")),
         DocumentEdge.Dependency.Create(GidRef.Create(
            "D5/S3/Combinatorics/CayleySumCodes/QuaternionDihedralCounterexamples")),
         DocumentEdge.Dependency.Create(GidRef.Create(
            "D5/S3/Combinatorics/CayleySumCodes/PerfectCodeTransversal"))]));
}
